8	const TMP_DIR_NAME = '.syncbox-tmp';
9	
10	function hasLoneSurrogate(str) {
11	  for (let i = 0; i < str.length; i++) {
12	    const code = str.charCodeAt(i);
13	    if (code >= 0xd800 && code <= 0xdbff) {
14	      const next = str.charCodeAt(i + 1);
15	      if (!(next >= 0xdc00 && next <= 0xdfff)) return true;
16	      i++;
17	    } else if (code >= 0xdc00 && code <= 0xdfff) {
18	      return true;
19	    }
20	  }
21	  return false;
22	}
23	
24	function isValidSegment(segment) {
25	  if (segment === '' || segment === '.' || segment === '..') return false;
26	  if (segment.includes('�')) return false;
27	  if (hasLoneSurrogate(segment)) return false;
28	  return true;
29	}
30	
31	// rawKeyPath is the raw (still percent-encoded) part of the URL after
32	// "/blobs/". Returns the decoded POSIX-style key, or null if it is not a
33	// valid, safely routable key (directory traversal, absolute path, empty
34	// segments, malformed encoding, unrepresentable filename, ...).
35	function parseBlobKey(rawKeyPath) {
36	  if (rawKeyPath === '') return null;
37	
38	  const rawSegments = rawKeyPath.split('/');
39	  const decodedSegments = [];
40	  for (const rawSegment of rawSegments) {
41	    if (rawSegment === '') return null;
42	    let decoded;
43	    try {
44	      decoded = decodeURIComponent(rawSegment);
45	    } catch {
46	      return null;
47	    }
48	    decodedSegments.push(decoded);
49	  }
50	
51	  // Re-split after decoding: a percent-encoded "/" inside a raw segment
52	  // (e.g. "..%2Fx") only becomes a path separator once decoded, and must
53	  // go through the same traversal checks as a literal "/" would.
54	  const key = decodedSegments.join('/');
55	  const finalSegments = key.split('/');
56	  for (const segment of finalSegments) {
57	    if (!isValidSegment(segment)) return null;
58	  }
59	  // The temp-file directory lives inside dataDir under this name. Reserve
60	  // it from the key namespace so a PUT can never write into (or a GET/DELETE
61	  // read out of) the same directory the atomic-write machinery uses.
62	  if (finalSegments[0] === TMP_DIR_NAME) return null;
63	
64	  return key;
65	}
66	
67	function resolveDestPath(dataDir, key) {
68	  const root = path.resolve(dataDir);
69	  const dest = path.resolve(root, key);
70	  if (dest !== root && !dest.startsWith(root + path.sep)) {
71	    throw new Error('key escapes data dir');
72	  }
73	  return dest;
74	}
75	
76	async function putBlob(dataDir, key, buffer) {
77	  const destPath = resolveDestPath(dataDir, key);
78	  const tmpDir = path.join(dataDir, TMP_DIR_NAME);
79	  await fsp.mkdir(tmpDir, { recursive: true });
80	  await fsp.mkdir(path.dirname(destPath), { recursive: true });
81	
82	  const tempPath = path.join(tmpDir, `${crypto.randomBytes(16).toString('hex')}.tmp`);
83	  try {
84	    // 'wx' fails loudly on a name collision instead of silently clobbering
85	    // another in-flight write's temp file (the random name makes this
86	    // astronomically unlikely, but it's free to guard against).
87	    await fsp.writeFile(tempPath, buffer, { flag: 'wx' });
88	    await fsp.rename(tempPath, destPath);
89	  } catch (err) {
90	    await fsp.unlink(tempPath).catch(() => {});
91	    throw err;
92	  }
93	
94	  const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
95	  return { key, sha256, size: buffer.length };
